import { closeSync, openSync, readdirSync, readSync } from "node:fs";
import { join } from "node:path";

/** Scan generated bytes without following links or printing a credential. */
export function findCanaryFiles(root, canaries) {
  const needles = canaries.filter(Boolean).map(value => Buffer.from(value));
  if (!needles.length) throw new Error("At least one synthetic canary is required.");
  const overlap = Math.max(...needles.map(value => value.length)) - 1;
  const findings = [];
  for (const entry of readdirSync(root, { withFileTypes: true })) {
    const path = join(root, entry.name);
    if (entry.isDirectory()) { findings.push(...findCanaryFiles(path, canaries)); continue; }
    if (!entry.isFile()) continue;
    const fd = openSync(path, "r");
    let previous = Buffer.alloc(0);
    try {
      const chunk = Buffer.alloc(64 * 1024);
      for (let count; (count = readSync(fd, chunk)) > 0;) {
        const bytes = Buffer.concat([previous, chunk.subarray(0, count)]);
        if (needles.some(needle => bytes.includes(needle))) { findings.push(path); break; }
        previous = bytes.subarray(Math.max(0, bytes.length - overlap));
      }
    } finally { closeSync(fd); }
  }
  return findings;
}
